1	//! What business the MHPCO will entertain at all: the office's grounds for
2	//! refusing a quote outright, and for refusing to settle an incident.
3	//!
4	//! This is the counter clerk's judgement, settled before any price is quoted
5	//! or any clause applied. It changes when the office tightens or loosens what
6	//! it will take on -- a type struck from the price list, a damage report it
7	//! will no longer read against a policy, an amount it will not entertain --
8	//! independently of what the office then charges for the business it accepts,
9	//! and independently of what its clauses reimburse once a claim is admitted.
10	
11	use std::collections::BTreeMap;
12	
13	use crate::coverage::covers_of_type;
14	use crate::pricing::is_listed;
15	use crate::{Damage, Item};
16	
17	/// The MHPCO refuses business it has no rule for.
18	#[derive(Debug, PartialEq, Eq)]
19	pub enum Refusal {
20	    UnlistedItemType(String),
21	    OverclaimedItemType(String),
22	    NegativeDamageAmount(i64),
23	}
24	
25	/// Why the office would refuse to insure this list of items, if it would.
26	/// Acceptance is settled before any pricing: the office only quotes business
27	/// its rules cover, and it names the first item it cannot place.
28	pub(crate) fn refusal_to_insure(items: &[Item]) -> Option<Refusal> {
29	    items
30	        .iter()
31	        .find(|item| !is_listed(item))
32	        .map(|unlisted| Refusal::UnlistedItemType(unlisted.item_type.clone()))
33	}
34	
35	/// Why the office would refuse to settle this incident against these covers,
36	/// if it would. Admissibility is settled before any clause is applied: the
37	/// office entertains no more damage of a type than the policy carries cover
38	/// of that type, which refuses an item the policy does not cover at all --
39	/// including a type the office does not even list -- by the same rule.
40	pub(crate) fn refusal_to_settle(insured: &[Item], damages: &[Damage]) -> Option<Refusal> {
41	    if let Some(negative) = damages.iter().find(|damage| damage.amount < 0) {
42	        return Some(Refusal::NegativeDamageAmount(negative.amount));
43	    }
44	    let mut reported: BTreeMap<&str, usize> = BTreeMap::new();
45	    for damage in damages {
46	        *reported.entry(damage.item_type.as_str()).or_default() += 1;
47	    }
48	    reported
49	        .into_iter()
50	        .find(|(item_type, count)| *count > covers_of_type(insured, item_type))
51	        .map(|(overclaimed, _)| Refusal::OverclaimedItemType(overclaimed.to_string()))
52	}
