21	pub struct Customer {
22	    pub years_with_mhpco: i64,
23	}
24	
25	pub struct Item {
26	    pub item_type: String,
27	    pub material: String,
28	    pub cursed: bool,
29	    pub enchantment: i64,
30	}
31	
32	const PROCESSING_FEE: i64 = 5;
33	
34	pub struct Damage {
35	    pub item_type: String,
36	    pub amount: i64,
37	}
38	
39	pub struct Settlement {
40	    pub payout: i64,
41	    pub remaining_cap: i64,
42	}
43	
44	pub struct Policy<'a> {
45	    insured: &'a [Item],
46	    exposure: PolicyExposure,
47	}
48	
49	impl<'a> Policy<'a> {
50	    pub fn insuring(items: &'a [Item]) -> Self {
51	        Policy {
52	            insured: items,
53	            exposure: PolicyExposure::on_policy_covering(items),
54	        }
55	    }
56	
57	    /// What the office settles for an incident: the clauses reimburse each
58	    /// damage reported, and the policy's remaining exposure decides how much
59	    /// of that total is actually paid.
60	    pub fn claim(&mut self, damages: &[Damage]) -> Result<Settlement, Refusal> {
61	        if let Some(refusal) = refusal_to_settle(self.insured, damages) {
62	            return Err(refusal);
63	        }
64	        let reimbursed = self.incident_reimbursement(damages);
65	        Ok(self
66	            .exposure
67	            .settle(round_payout_in_mhpco_favor(reimbursed)))
68	    }
69	
70	    /// What the office's clauses reimburse for an incident, before its
71	    /// exposure limit is brought to bear: every damage the incident reported,
72	    /// each judged against the cover it names.
73	    fn incident_reimbursement(&self, damages: &[Damage]) -> f64 {
74	        damages
75	            .iter()
76	            .map(|damage| {
77	                damage_reimbursement(damage, cover_claimed_against(self.insured, damage))
78	            })
79	            .sum()
80	    }
81	}
82	
83	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
84	/// modifiers scale the policy base premium, while item-specific modifiers are
85	/// measured against their own item's base premium and are added alongside, so
86	/// a curse never surcharges the rest of the policy.
87	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
88	    let base = policy_base_premium(items);
89	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
90	}
91	
92	pub fn quote(
93	    customer: &Customer,
94	    items: &[Item],
95	    previous_quotes: usize,
96	) -> Result<i64, Refusal> {
97	    if let Some(refusal) = refusal_to_insure(items) {
98	        return Err(refusal);
99	    }
100	    let premium = premium_before_fee(customer, items, previous_quotes);
101	    Ok(round_premium_in_mhpco_favor(premium) + PROCESSING_FEE)
102	}
